<?php
declare(strict_types=1);
use DataForm5\Licensing\Contracts\LicenseManagerInterface;use DataForm5\Licensing\Core\ArrayLicenseProvider;use DataForm5\Licensing\Core\LicenseManager;use DataForm5\Licensing\Exceptions\LicenseException;
$root=dirname(__DIR__);$kernel=require $root.'/bootstrap/app.php';$manager=$kernel->container()->get(LicenseManagerInterface::class);assert($manager->valid());assert($manager->allows('core.health'));$provider=new ArrayLicenseProvider(['license'=>['id'=>'test','holder'=>'Tester','edition'=>'enterprise','capabilities'=>['reporting.export','projects.manage'],'products'=>['dataform'],'expires_at'=>'2026-08-01T00:00:00+00:00','grace_days'=>10]]);$licensed=new LicenseManager($provider,false);assert($licensed->status(new DateTimeImmutable('2026-08-06T00:00:00+00:00'))==='grace');assert($licensed->allows('reporting.export',['product'=>'dataform','at'=>new DateTimeImmutable('2026-08-06T00:00:00+00:00')]));assert(!$licensed->allows('reporting.export',['product'=>'dialog','at'=>new DateTimeImmutable('2026-08-06T00:00:00+00:00')]));assert($licensed->status(new DateTimeImmutable('2026-08-20T00:00:00+00:00'))==='expired');$thrown=false;try{$licensed->requireCapability('admin.superuser',['product'=>'dataform','at'=>new DateTimeImmutable('2026-08-06T00:00:00+00:00')]);}catch(LicenseException){$thrown=true;}assert($thrown);echo "PASS: Licensing and Capability Layer\n";
